update public.books set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('geographicReview','{"reviewedAt":"2026-10-13","scope":"geographical-placement-and-visibility-of-imported-records","regionalPlaces":[{"id":"regional-rokovoko","keys":["Rokovoko"],"evidencePriority":["Rokovoko"],"categories":{},"sceneText":"The original reference is retained. This regional position gives geographical context; narrative category is assessed separately for each section.","evidenceLabel":"Original section evidence","place":{"name":"Rokovoko · regional position","area":"South Pacific","coords":[-20,-150],"kind":"uncertain","zoom":3,"checked":"2026-10-13","status":"Uncertain regional position","note":"Fictional or unnamed setting. The diamond marks only a representative point in South Pacific; it does not identify a real town, island, address or boundary.","method":"The region or literary model is supported by the textual/critical source. The rounded map point is selected within that area for orientation only; distances and routes are not reconstructed.","aliases":["Rokovoko"],"positionSource":{"url":"https://www.openstreetmap.org/#map=3/-20/-150","label":"OpenStreetMap · representative regional view"},"narrativeSource":{"url":"https://melville.electroniclibrary.org/editions/versions-of-moby-dick/12-biographical","label":"Textual / critical geographical evidence"},"geographicReview":{"reason":"L’edizione critica identifica il luogo come isola pacifica inventata; il testo dà soltanto ovest e sud. Punto oceanico regionale, senza identificare un’isola.","precision":"region","realWorldIdentity":"not-established"}}}],"hiddenUnlocatedKeys":["Crossed Harpoons","Sword-Fish Inn","Spouter-Inn","Try Pots","Pupella","Bamboo"],"counts":{"mappedExisting":276,"unlocatedRecords":14,"unlocatedKeys":13,"newRegionalPlaces":1,"regionalReferences":1,"hiddenRecords":6,"retainedRecords":7},"analysisNote":"Le locande inventate non aggiungono una posizione utile rispetto a New Bedford/Nantucket. Arsacides e Tranque restano visibili come problema geografico documentato: le fonti mescolano Cile e Salomone; non sono equiparate a un punto certo. I luoghi della perdita e del salvataggio restano senza punto esatto."}'::jsonb) where id='moby-dick';

update public.books set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('geographicReview','{"reviewedAt":"2026-10-13","scope":"geographical-placement-and-visibility-of-imported-records","regionalPlaces":[{"id":"regional-little-girl-bay","keys":["Little Girl Bay"],"evidencePriority":["Little Girl Bay"],"categories":{},"sceneText":"The original reference is retained. This regional position gives geographical context; narrative category is assessed separately for each section.","evidenceLabel":"Original section evidence","place":{"name":"Little Girl Bay · regional position","area":"Lake Superior","coords":[47,-88],"kind":"uncertain","zoom":5,"checked":"2026-10-13","status":"Uncertain regional position","note":"Fictional or unnamed setting. The diamond marks only a representative point in Lake Superior; it does not identify a real town, island, address or boundary.","method":"The region or literary model is supported by the textual/critical source. The rounded map point is selected within that area for orientation only; distances and routes are not reconstructed.","aliases":["Little Girl Bay"],"positionSource":{"url":"https://www.openstreetmap.org/#map=5/47/-88","label":"OpenStreetMap · representative regional view"},"narrativeSource":{"url":"https://standardebooks.org/ebooks/f-scott-fitzgerald/the-great-gatsby/text/chapter-6","label":"Textual / critical geographical evidence"},"geographicReview":{"reason":"Il contesto del capitolo VI stabilisce Lake Superior, pur senza una baia univoca. Il punto rappresenta il lago; non identifica Little Girl’s Point né una riva precisa.","precision":"region","realWorldIdentity":"not-established"}}}],"hiddenUnlocatedKeys":["Nick’s cottage","Buchanans’ house and Daisy’s dock","Gatsby’s mansion","Wilson’s garage and Michaelis’s restaurant","Eckleburg’s billboard","Myrtle’s apartment","Probity Trust","Gatsby’s mansion and party driveway","Nick’s cottage and Gatsby’s interiors","Castle Rackrent · literary allusion","Plaza suite","Wilson’s garage and accident site","Buchanans’ house","Gatsby’s swimming pool","Swastika Holding Company office"],"counts":{"mappedExisting":88,"unlocatedRecords":38,"unlocatedKeys":38,"newRegionalPlaces":1,"regionalReferences":1,"hiddenRecords":15,"retainedRecords":22},"analysisNote":"West Egg, East Egg e Valley of Ashes hanno già aree e modelli dichiarati. Le case e le aziende inventate restano nell’analisi; gli edifici storici, i toponimi omonimi irrisolti e i viaggi geografici restano disponibili. Port Roosevelt/Gad’s Hill non vengono equiparati a un porto moderno senza prova."}'::jsonb) where id='gatsby';

update public.books set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('geographicReview','{"reviewedAt":"2026-10-13","scope":"geographical-placement-and-visibility-of-imported-records","regionalPlaces":[{"id":"regional-agerstown","keys":["Pencey / Agerstown / Thomsen Hill","Pencey / Agerstown","Pencey Prep","Spencer’s house · Anthony Wayne Avenue","Spencer’s room","Ossenburger Memorial Wing","Dormitory washroom","Dormitory room / parked car","Agerstown station / train"],"evidencePriority":["Pencey / Agerstown / Thomsen Hill","Pencey / Agerstown","Pencey Prep","Spencer’s house · Anthony Wayne Avenue","Spencer’s room","Ossenburger Memorial Wing","Dormitory washroom","Dormitory room / parked car","Agerstown station / train"],"categories":{},"sceneText":"The original reference is retained. This regional position gives geographical context; narrative category is assessed separately for each section.","evidenceLabel":"Original section evidence","place":{"name":"Pencey / Agerstown / Thomsen Hill · regional position","area":"Pennsylvania","coords":[41,-77.5],"kind":"uncertain","zoom":5,"checked":"2026-10-13","status":"Uncertain regional position","note":"Fictional or unnamed setting. The diamond marks only a representative point in Pennsylvania; it does not identify a real town, island, address or boundary.","method":"The region or literary model is supported by the textual/critical source. The rounded map point is selected within that area for orientation only; distances and routes are not reconstructed.","aliases":["Pencey / Agerstown / Thomsen Hill"],"positionSource":{"url":"https://www.openstreetmap.org/#map=5/41/-77.5","label":"OpenStreetMap · representative regional view"},"narrativeSource":{"url":"https://core-docs.s3.us-east-1.amazonaws.com/documents/asset/uploaded_file/1759/ohs/4407599/Catcher_in_the_Rye.pdf#page=7","label":"Textual / critical geographical evidence"},"geographicReview":{"reason":"Il capitolo I indica Agerstown, Pennsylvania. Non viene sostituita con Valley Forge o con un campus reale.","precision":"region","realWorldIdentity":"not-established"}}}],"hiddenUnlocatedKeys":["Spencer’s house · Anthony Wayne Avenue","Spencer’s room","Ossenburger Memorial Wing","Dormitory washroom","Dormitory room / parked car","Edmont Hotel · unverified address","Lavender Room","Ernie’s interior","Imagined rye field and cliff","Antolini apartment interior"],"counts":{"mappedExisting":52,"unlocatedRecords":35,"unlocatedKeys":29,"newRegionalPlaces":1,"regionalReferences":9,"hiddenRecords":8,"retainedRecords":18},"analysisNote":"Agerstown/Pencey è ora un unico riferimento regionale. Gli interni inventati non ricevono punti duplicati. Whooton/Elkton Hills e Lake Sedebego restano identificazioni irrisolte, senza sostituzioni con luoghi biografici. Il Seton/Wicker Bar conserva il problema documentato di 54th Street contro il vero hotel di 40th Street."}'::jsonb) where id='holden';

