update public.books set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('geographicReview','{"reviewedAt":"2026-10-13","scope":"geographical-placement-and-visibility-of-imported-records","regionalPlaces":[{"id":"regional-pokrovskoe","keys":["pokrovskoe","levin-house","pokrovskoye-arrival","nursery","mowing","kalinovy","mashkin","woodcock-clearing","kolok","storm-woods","levin-road"],"evidencePriority":["pokrovskoe","levin-house","pokrovskoye-arrival","nursery","mowing","kalinovy","mashkin","woodcock-clearing","kolok","storm-woods","levin-road"],"categories":{"226":"action"},"sceneText":"The original reference is retained. This regional position gives geographical context; narrative category is assessed separately for each section.","evidenceLabel":"Original section evidence","place":{"name":"Pokrovskoye, Levin’s estate · regional position","area":"Tula region · literary model","coords":[54,37.5],"kind":"uncertain","zoom":6,"checked":"2026-10-13","status":"Uncertain regional position","note":"Fictional or unnamed setting. The diamond marks only a representative point in Tula region · literary model; it does not identify a real town, island, address or boundary.","method":"The region or literary model is supported by the textual/critical source. The rounded map point is selected within that area for orientation only; distances and routes are not reconstructed.","aliases":["Pokrovskoye, Levin’s estate"],"positionSource":{"url":"https://www.openstreetmap.org/#map=6/54/37.5","label":"OpenStreetMap · representative regional view"},"narrativeSource":{"url":"https://ypmuseum.ru/event/1283","label":"Textual / critical geographical evidence"},"geographicReview":{"reason":"Il museo Yasnaya Polyana documenta il confronto Pokrovskoye/Yasnaya Polyana. Riferimento regionale del modello, senza equiparare l’azienda di Levin a una casa reale o scegliere un omonimo moderno.","precision":"region","realWorldIdentity":"not-established"}}}],"hiddenUnlocatedKeys":["oblonsky-hou